assert hashlib.sha256(NEW).hexdigest()==NEW_HASH
ast.parse(NEW.decode('utf8'))
for needed in (SOLVER,APP,BOARD):
    if not needed.is_file():
        raise SystemExit(f'Cannot find {needed}. Run installer from the correct repository root after installing Queens solver.')
if not TARGET.is_file():
    raise SystemExit('Existing Queens screenshot importer is missing. Install the earlier screenshot importer first.')
old=TARGET.read_bytes()
digest=hashlib.sha256(old).hexdigest()
if digest==NEW_HASH:
    print('Already installed: automatic Queens cropping.')
elif digest!=OLD_HASH:
    raise SystemExit('The installed importer has been customised or differs from the supported earlier version. Refusing to overwrite it. Share the current file for a targeted patch.')
else:
    backup=TARGET.with_name(TARGET.name+'.pre-autocrop.bak')
    if backup.exists() and backup.read_bytes()!=old:
        raise SystemExit('A different backup already exists; refusing to replace it.')
    backup.write_bytes(old)
    TARGET.write_bytes(NEW)
    print('Updated:',TARGET)
    print('Backup:',backup)
ignore=ROOT/'.gitignore'
lines=ignore.read_text(encoding='utf8').splitlines() if ignore.exists() else []
for pattern in ('queens-board*.png','queens-preview*.png','scripts/import_queens_screenshot.py.pre-autocrop.bak'):
    if pattern not in lines:
        lines.append(pattern)
ignore.write_text('\n'.join(lines)+'\n',encoding='utf8')
print('Auto-crop importer installed; gitignore safeguards added.')
print('Preview example: python scripts/import_queens_screenshot.py queens-board.png --date 2026-11-02 --number 916 --size 7')
